sp_widget.client_script:
api.controller = function($scope, spUtil, $location, $timeout, $filter) {
    var c = this;

    // View States
    c.data.selectedSwap = null;
    c.data.swapDetails = null;
    c.data.isLoadingDetails = false;
    c.data.isCancelling = false;

    // Filters & Pagination
    c.searchSwap = '';
    c.listFilter = 'pending';
    c.sapFilter = '';        // '' | 'success' | 'pending' | 'failed'
    c.currentPage = 1;
    c.itemsPerPage = 10;
    c.pendingCount = 0;
    c.historyCount = 0;

    // File Upload State
    c.isUploadingFile = false;

    // SAP Retry State
    c.sapRetrying = false;
    c.sapRetryMsg = '';

    // INR Currency Formatter
    c.formatINR = function(val) {
        if (val === undefined || val === null || val === '') return '0.00';
        var num = parseFloat(val);
        if (isNaN(num)) return '0.00';
        return num.toLocaleString('en-IN', { minimumFractionDigits: 2, maximumFractionDigits: 2 });
    };

    function isPending(item) {
        return !!item && (item.internalState === 'pending' || item.internalState === 'work');
    }

    c.updateCounts = function() {
        if (!c.data.list) return;
        c.pendingCount = c.data.list.filter(function(i) { return isPending(i); }).length;
        c.historyCount = c.data.list.filter(function(i) { return !isPending(i); }).length;
    };

    c.setFilter = function(filterType) {
        c.listFilter = filterType;
        c.currentPage = 1;
    };

    // SAP Quick Filters
    c.setSapFilter = function(status) {
        c.sapFilter = (c.sapFilter === status) ? '' : status;
        c.currentPage = 1;
    };

    c.countBySap = function(status) {
        return (c.data.list || []).filter(function(b) {
            return (b.sap_status || 'na') === status;
        }).length;
    };

    c.hasSapStats = function() {
        return (c.data.list || []).some(function(b) {
            return b.sap_status && b.sap_status !== 'na';
        });
    };

    c.clearAllFilters = function() {
        c.searchSwap = '';
        c.sapFilter = '';
        c.currentPage = 1;
    };

    c.getFilteredSwaps = function() {
        var arr = c.data.list || [];
        if (c.listFilter === 'pending') {
            arr = arr.filter(function(b) { return isPending(b); });
        } else if (c.listFilter === 'completed') {
            arr = arr.filter(function(b) { return !isPending(b); }).slice().reverse();
        } else if (c.listFilter === 'all') {
            arr = arr.slice();
        }

        if (c.sapFilter) {
            arr = arr.filter(function(b) { return (b.sap_status || 'na') === c.sapFilter; });
        }

        if (c.searchSwap) {
            var s = c.searchSwap.toLowerCase();
            arr = arr.filter(function(b) {
                return (b.number && b.number.toLowerCase().indexOf(s) > -1) ||
                       (b.pan && b.pan.toLowerCase().indexOf(s) > -1) ||
                       (b.donee_site && b.donee_site.toLowerCase().indexOf(s) > -1) ||
                       (b.donor_site && b.donor_site.toLowerCase().indexOf(s) > -1) ||
                       (b.requested_by && b.requested_by.toLowerCase().indexOf(s) > -1);
            });
        }
        return arr;
    };

    c.getPaginatedSwaps = function() {
        var filtered = c.getFilteredSwaps();
        var startIndex = (c.currentPage - 1) * c.itemsPerPage;
        return filtered.slice(startIndex, startIndex + c.itemsPerPage);
    };

    c.totalPages = function() {
        return Math.ceil(c.getFilteredSwaps().length / c.itemsPerPage) || 1;
    };

    c.getMathMin = function(a, b) {
        return Math.min(a, b);
    };

    c.changePage = function(delta) {
        c.currentPage += delta;
    };

    // SAP send-back class
    c.sbClass = function(status) {
        var s = (status || '').toLowerCase();
        if (s === 'success' || s === 'processed') return 'approved';
        if (s === 'failed') return 'rejected';
        return 'pending';
    };

    // Latest send-back rows per site code
    c.getSapSiteRows = function() {
        var list = (c.data.swapDetails && c.data.swapDetails.sendBackList) || [];
        var seen = {}, out = [];
        list.forEach(function(r) {
            var k = (r.customer_code || 'ALL') + '|' + (r.credit_segment || 'ALL');
            if (seen[k]) return;
            seen[k] = true;
            out.push(r);
        });
        return out;
    };

    // Master List Loader
    c.fetchSwapList = function() {
        c.data.isFetchingSwaps = true;
        c.server.get({ action: 'fetch_swaps' }).then(function(r) {
            c.data.isFetchingSwaps = false;
            c.data.list = (r.data && r.data.list) ? r.data.list : [];
            c.updateCounts();

            var reqNum = $location.search().number;
            if (reqNum && !c.data.selectedSwap) {
                var target = c.data.list.find(function(s) { return s.number === reqNum; });
                if (target) c.viewDetails(target);
            }
        });
    };

    // View Details Definition
    c.viewDetails = function(swap) {
        if (!swap) return;

        c.data.selectedSwap = swap;
        c.data.isLoadingDetails = true;
        c.sapRetryMsg = '';

        $location.search('number', swap.number);

        c.server.get({
            action: 'get_swap_details',
            swapSysId: swap.sys_id
        }).then(function(res) {
            c.data.swapDetails = {
                approvals: (res.data && res.data.approvalData) ? res.data.approvalData : [],
                extended: (res.data && res.data.extendedDetails) ? res.data.extendedDetails : { donee: {}, donor: {} },
                justification: (res.data && res.data.justification) ? res.data.justification : '',
                attachments: (res.data && res.data.attachments) ? res.data.attachments : [],
                sendBackList: (res.data && res.data.sendBackList) ? res.data.sendBackList : []
            };
            c.data.isLoadingDetails = false;
        });
    };

    // SAP Retry Action (Admin Only)
    c.retrySap = function(swap) {
        if (c.sapRetrying || !swap) return;
        if (!c.data.isAdmin) return;
        if (!confirm('Retry the SAP update for ' + swap.number + '?')) return;

        c.sapRetrying = true;
        c.sapRetryMsg = '';

        c.server.get({ action: 'retry_sap', swapSysId: swap.sys_id }).then(function(resp) {
            c.sapRetrying = false;
            var d = resp.data || {};
            c.sapRetryMsg = d.retryResult ? d.retryResult.message : '';
            if (d.sap) {
                angular.extend(c.data.selectedSwap, d.sap);
            }
            if (d.sendBackList && c.data.swapDetails) {
                c.data.swapDetails.sendBackList = d.sendBackList;
            }
            if (d.retryResult && d.retryResult.ok) {
                c.pollSap(swap.sys_id, 4);
            }
        }).catch(function() {
            c.sapRetrying = false;
            c.sapRetryMsg = 'Could not submit retry. Please try again.';
        });
    };

    c.pollSap = function(sysId, tries) {
        $timeout(function() {
            c.server.get({ action: 'get_sap_status', swapSysId: sysId }).then(function(resp) {
                var d = resp.data || {};
                if (d.sap && c.data.selectedSwap && c.data.selectedSwap.sys_id === sysId) {
                    angular.extend(c.data.selectedSwap, d.sap);
                }
                if (d.sendBackList && c.data.swapDetails) {
                    c.data.swapDetails.sendBackList = d.sendBackList;
                }
                var stillRunning = d.sap && d.sap.sap_status === 'pending';
                if (stillRunning && tries > 1) {
                    c.pollSap(sysId, tries - 1);
                } else {
                    c.sapRetryMsg = '';
                }
            });
        }, 15000);
    };

    // Direct Attachment Upload to Swap Record
    c.uploadDirectAttachment = function(element) {
        var file = element.files[0];
        if (!file) return;

        if (file.size > 5 * 1024 * 1024) {
            spUtil.addErrorMessage("File size exceeds 5MB limit.");
            element.value = '';
            return;
        }

        c.isUploadingFile = true;
        var reader = new FileReader();
        reader.onload = function(e) {
            var base64Data = e.target.result.split(',')[1];
            c.server.get({
                action: 'upload_document',
                swapSysId: c.data.selectedSwap.sys_id,
                fileName: file.name,
                fileType: file.type,
                fileData: base64Data
            }).then(function(res) {
                c.isUploadingFile = false;
                element.value = '';
                spUtil.addInfoMessage("Document uploaded successfully.");
                c.data.swapDetails.attachments = res.data.attachments || [];
            }).catch(function() {
                c.isUploadingFile = false;
                element.value = '';
                spUtil.addErrorMessage("Failed to upload document.");
            });
        };
        reader.readAsDataURL(file);
    };

    // Cancel Swap Request
    c.cancelRequest = function(swap) {
        if (confirm("Are you sure you want to cancel request " + swap.number + "? Background approval workflows will be terminated.")) {
            c.data.isCancelling = true;

            c.server.get({
                action: 'cancel_swap',
                swapSysId: swap.sys_id
            }).then(function(response) {
                c.data.isCancelling = false;
                if (response.data && response.data.success) {
                    spUtil.addInfoMessage("Request " + swap.number + " has been cancelled.");
                    c.goBack();
                    c.fetchSwapList();
                } else {
                    spUtil.addErrorMessage("Unable to cancel request.");
                }
            });
        }
    };

    c.goBack = function() {
        c.data.selectedSwap = null;
        c.data.swapDetails = null;
        c.sapRetryMsg = '';
        $location.search('number', null);
    };

    c.$onInit = function() {
        c.fetchSwapList();
    };
};

sp_widget.css:
@import url('https://fonts.googleapis.com/css2?family=Oxygen:wght@300;400;700&display=swap');

/* ---------------------------------------------------------------------
0. Page shell + header banner
--------------------------------------------------------------------- */
.clm-ls, .clm-ls *, .clm-ls *::before, .clm-ls *::after { box-sizing:border-box; }
.clm-ls { background:white; padding:24px 32px; border-radius:8px; color:#1a1a1a; font-size:13px; }

.clm-hero {
  position:relative; overflow:hidden; border-radius:12px; padding:26px 30px; min-height:132px;
  display:flex; align-items:center; justify-content:space-between; gap:20px; flex-wrap:wrap;
  box-shadow:0 10px 28px rgba(122,16,18,.25);
  background:
    linear-gradient(90deg, #7A1012 0%, #9E1715 40%, rgba(158,23,21,.88) 52%, rgba(158,23,21,.35) 68%, rgba(158,23,21,0) 82%),
    radial-gradient(circle at 72% 100%, #F3CE52 0 30px, #7A1012 30px 33px, #F9A04A 33px 44px, #7A1012 44px 47px, #F3712A 47px 58px, transparent 58px),
    repeating-conic-gradient(from -90deg at 72% 100%, #F3CE52 0deg 7deg, #F3712A 7deg 14deg, #9E1715 14deg 21deg, #DA1D26 21deg 28deg),
    #9E1715;
}

/* Breadcrumb Trail inside Banner */
.clm-hero-breadcrumb { display:flex; align-items:center; gap:8px; margin-bottom:10px; font-size:13px; font-weight:600; color:#fbe3cf; }
.clm-hero-breadcrumb .clm-breadcrumb-link { color:#F3CE52; text-decoration:none; display:inline-flex; align-items:center; gap:5px; cursor:pointer; }
.clm-hero-breadcrumb .clm-breadcrumb-link:hover { text-decoration:underline; opacity:0.9; }
.clm-hero-breadcrumb .clm-breadcrumb-sep { font-size:12px; opacity:0.7; color:#ffffff; }
.clm-hero-breadcrumb .clm-breadcrumb-curr { color:#ffffff; font-weight:700; }

.clm-hero-text { position:relative; z-index:1; flex:1 1 420px; min-width:0; }
.clm-hero-bar { width:44px; height:6px; border-radius:3px; background:linear-gradient(90deg,#F3CE52,#F3712A); margin-bottom:12px; }
.clm-hero-title { margin:0; font-size:26px; font-weight:700; line-height:1.25; color:#ffffff; }
.clm-hero-accent { color:#F3CE52; }
.clm-hero-sub { margin:6px 0 0; font-size:15px; color:#fbe3cf; }
.clm-hero-tag {
  display:inline-flex; align-items:center; gap:6px; margin-top:12px; padding:4px 10px; border-radius:12px;
  background:rgba(122,16,18,.6); border:1px solid rgba(243,206,82,.6); color:#F3CE52; font-size:12px; font-weight:700;
}
.clm-hero-chips { display:flex; flex-wrap:wrap; gap:8px; margin-top:14px; }
.clm-hero-chip {
  display:inline-flex; align-items:center; gap:6px; padding:4px 10px; border-radius:12px;
  background:#ffffff; border:1px solid #ffffff; font-size:12px; font-weight:700; color:#1a1a1a; white-space:nowrap;
}
.clm-hero-chip-k { font-weight:400; color:#5a6a7a; }

.clm-hero-side { position:relative; z-index:1; display:flex; flex-direction:column; align-items:flex-end; gap:12px; }
.clm-hero-actions-row { display:flex; align-items:center; gap:8px; flex-wrap:wrap; }
.clm-hero-btn {
  display:inline-flex; align-items:center; gap:8px; padding:9px 18px; border-radius:8px; cursor:pointer;
  background:#F3CE52; color:#7A1012; border:2px solid #7A1012; font-size:14px; font-weight:700;
  box-shadow:0 0 0 2px rgba(243,206,82,.35);
}
.clm-hero-btn:hover { background:#ffdf6e; }
.clm-hero-stat { padding:12px 20px; border-radius:10px; background:rgba(122,16,18,.92); border-left:4px solid #F3CE52; text-align:right; }
.clm-hero-stat-v { font-size:34px; font-weight:700; line-height:1.1; letter-spacing:1px; color:#F3CE52; white-space:nowrap; }
.clm-hero-stat-v.is-amount { font-size:26px; letter-spacing:.5px; }
.clm-hero-stat-k { margin-top:4px; font-size:12px; font-weight:700; text-transform:uppercase; letter-spacing:.6px; color:#fbd9bd; }

/* ---------------------------------------------------------------------
1. Section
--------------------------------------------------------------------- */
.clm-section { margin-top:20px; background:#fff; border:1px solid #e0e6ed; border-radius:10px; padding:28px 32px; }
.clm-section-title {
  display:flex; align-items:center; gap:12px; margin-bottom:4px;
  font-size:14px; font-weight:700; color:#1a1a1a; text-transform:uppercase; letter-spacing:1px;
}
.clm-section-num {
  width:26px; height:26px; border-radius:50%; background:#F3D54E; color:#1a1a1a; flex-shrink:0;
  font-size:13px; font-weight:700; display:inline-flex; align-items:center; justify-content:center;
}
.clm-ls-gap { margin-top:32px; }

/* ---------------------------------------------------------------------
2. Card (block) + chips
--------------------------------------------------------------------- */
.clm-block { margin-top:16px; background:#fff; border:1px solid #dde3ea; border-radius:8px; overflow:hidden; }
.clm-block-head {
  display:flex; align-items:center; justify-content:space-between; gap:12px 20px; flex-wrap:wrap;
  padding:14px 20px; background:#fafbfc; border-bottom:1px solid #dde3ea;
}
.clm-block-title {
  display:flex; align-items:center; gap:10px; font-size:13px; font-weight:700; color:#1a1a1a;
  text-transform:uppercase; letter-spacing:.8px;
}
.clm-block-title::before { content:""; width:4px; height:16px; border-radius:2px; background:#F3D54E; flex-shrink:0; }
.clm-block-sub { margin:4px 0 0 14px; font-size:12px; color:#5a6a7a; }
.clm-block-meta { display:flex; align-items:center; gap:8px; flex-wrap:wrap; }
.clm-chip {
  display:inline-flex; align-items:center; gap:6px; padding:4px 10px; background:#fff;
  border:1px solid #dde3ea; border-radius:12px; font-size:12px; font-weight:700; color:#1a1a1a; white-space:nowrap;
}
.clm-chip-k { font-weight:400; color:#5a6a7a; }
.clm-mr-clear { padding:4px 10px; border:1px solid #cdd4dc; border-radius:12px; background:#ffffff; color:#c0392b; font-size:12px; font-weight:700; cursor:pointer; }
.clm-mr-clear:hover { background:#fef5f4; border-color:#f5c2bc; }
.clm-tw-body { padding:18px 20px; }

/* ---------------------------------------------------------------------
3. SAP Sync Filter & Badges
--------------------------------------------------------------------- */
.clm-mr-sap-stats { margin-top:14px; padding:14px 16px; background:#ffffff; border:1px solid #dde3ea; border-radius:8px; }
.clm-mr-sap-title { font-size:12px; font-weight:700; color:#3a4451; text-transform:uppercase; letter-spacing:0.6px; margin-bottom:10px; }
.clm-mr-sap-tiles { display:grid; grid-template-columns:repeat(3, minmax(0, 1fr)); gap:10px; }
.clm-mr-sap-tile {
  display:flex; flex-direction:column; align-items:flex-start; gap:2px; padding:10px 12px; background:#ffffff;
  border:1px solid #dde3ea; border-left:4px solid #cdd4dc; border-radius:6px; cursor:pointer; font-family:inherit; text-align:left;
  transition:box-shadow .15s ease, transform .15s ease, background .15s ease;
}
.clm-mr-sap-tile:hover { box-shadow:0 4px 10px rgba(0,0,0,0.05); transform:translateY(-1px); }
.clm-mr-sap-tile.is-active { background:#fffcf0; border-color:#F3D54E; box-shadow:0 0 0 2px rgba(243,213,78,.35); }
.clm-mr-sap-tile.sap-success { border-left-color:#27ae60; }
.clm-mr-sap-tile.sap-pending { border-left-color:#E87722; }
.clm-mr-sap-tile.sap-failed  { border-left-color:#E23D28; }
.clm-mr-sap-k { font-size:11px; font-weight:700; color:#5a6a7a; text-transform:uppercase; letter-spacing:0.5px; }
.clm-mr-sap-v { font-size:20px; font-weight:700; color:#1a1a1a; line-height:1.1; }
.clm-mr-sap-tile.sap-success .clm-mr-sap-v { color:#1e8449; }
.clm-mr-sap-tile.sap-pending .clm-mr-sap-v { color:#b9650f; }
.clm-mr-sap-tile.sap-failed  .clm-mr-sap-v { color:#c0392b; }

.clm-badge { display:inline-block; padding:4px 10px; border-radius:4px; font-size:11px; font-weight:700; letter-spacing:0.5px; text-transform:uppercase; }
.clm-status-approved { background:#eafaf1; color:#1e8449; border:1px solid #a9dfbf; }
.clm-status-rejected { background:#fef5f4; color:#c0392b; border:1px solid #fadbd8; }
.clm-status-pending  { background:#eaf4fb; color:#1a5276; border:1px solid #aed6f1; }

.clm-sap { border:1px solid transparent; }
.clm-sap.sap-success, .clm-sap-banner.sap-success { background:#eafaf1; color:#1e8449; border-color:#a9dfbf; }
.clm-sap.sap-failed,  .clm-sap-banner.sap-failed  { background:#fef5f4; color:#c0392b; border-color:#f5c2bc; }
.clm-sap.sap-pending, .clm-sap-banner.sap-pending { background:#fffcf0; color:#8a6100; border-color:#F9E79F; }
.clm-sap-clickable { cursor:pointer; }
.clm-sap-clickable:hover { transform:translateY(-1px); }

.clm-sap-banner { display:flex; gap:12px; align-items:flex-start; padding:14px 24px; border-bottom:1px solid; border-radius:6px; margin-bottom:16px; }
.clm-sap-ico { font-size:20px; line-height:1.2; }
.clm-sap-title { font-size:13px; font-weight:700; text-transform:uppercase; letter-spacing:.6px; }
.clm-sap-msg { font-size:13px; margin-top:2px; color:#1a1a1a; }
.clm-sap-err { font-size:11.5px; margin-top:6px; color:#5a6a7a; font-family:monospace; }
.clm-sap-actions { margin-top:10px; }
.clm-sap-retry { background:#c0392b; color:#fff; height:36px; padding:0 16px; border:none; border-radius:4px; font-weight:700; cursor:pointer; }
.clm-sap-retry:hover:not(:disabled) { background:#a93226; }
.clm-sap-note { margin-top:8px; font-size:12px; font-weight:600; color:#5a6a7a; }

/* SAP Send-back details row */
.clm-sb-row { padding:12px 14px; margin-bottom:10px; background:#fafbfc; border:1px solid #dde3ea; border-radius:6px; }
.clm-sb-row:last-child { margin-bottom:0; }
.clm-sb-top { display:flex; align-items:center; justify-content:space-between; gap:8px; }
.clm-sb-when { font-size:11.5px; color:#7f8c9a; }
.clm-sb-meta { display:flex; flex-wrap:wrap; gap:4px 18px; margin-top:8px; font-size:12.5px; }
.clm-sb-meta .k { color:#7f8c9a; margin-right:4px; }
.clm-sb-err { margin-top:8px; padding:7px 10px; border-radius:6px; background:#fef5f4; border:1px solid #f5c2bc; font-size:12px; color:#8f1d16; }

/* ---------------------------------------------------------------------
4. Data table
--------------------------------------------------------------------- */
.clm-table-wrap { overflow-x:auto; border:1px solid #dde3ea; border-radius:8px; background:#fff; }
.clm-table { width:100%; border-collapse:collapse; font-size:13px; font-variant-numeric:tabular-nums; }
.clm-table th {
  background:#eef1f5; color:#2b3440; padding:12px 14px; font-size:12px; font-weight:700;
  text-transform:uppercase; letter-spacing:.6px; text-align:center; white-space:nowrap; border:1px solid #dde3ea;
}
.clm-table td { padding:14px; color:#1a1a1a; text-align:center; white-space:nowrap; border:1px solid #e6eaef; vertical-align:middle; }
.clm-table tr > :first-child { border-left:0; text-align:left; }
.clm-table tr > :last-child  { border-right:0; }
.clm-table thead tr:first-child th { border-top:0; }
.clm-table tbody tr:last-child td  { border-bottom:0; }
.clm-table .grp { border-left:2px solid #c9d1db !important; }
.clm-table .num { text-align:right; }

.clm-table tr.super th { letter-spacing:1px; padding:11px 14px; }
.clm-table th.bg-code  { background:#e3eefa; color:#0b5394; }
.clm-table th.bg-seg   { background:#f1f3f7; color:#3a4451; }
.clm-table th.bg-donee { background:#e6f4ea; color:#2e7d32; }
.clm-table th.bg-donor { background:#fdecea; color:#b3261e; }

.clm-cust-name { font-weight:700; color:#1a1a1a; }
.clm-cust-code { margin-top:2px; font-size:12px; font-weight:600; color:#5a6a7a; }
.v-bad { color:#c0392b !important; font-weight:700; }

/* ---------------------------------------------------------------------
5. Factor tiles + result row
--------------------------------------------------------------------- */
.clm-tw-factors { display:grid; grid-template-columns:repeat(3,minmax(0,1fr)); gap:12px; }
.clm-tw-factor { padding:12px 14px; border:1px solid #e0e6ed; border-radius:6px; background:#fafbfc; min-width:0; }
.clm-tw-factor-k { font-size:12px; color:#5a6a7a; margin-bottom:4px; }
.clm-tw-factor-v { font-size:16px; font-weight:700; color:#1a1a1a; white-space:nowrap; overflow:hidden; text-overflow:ellipsis; }
.clm-tw-factor-v.is-text { font-size:13.5px; white-space:normal; overflow:visible; }
.clm-tw-factor.is-ok  { background:#f4fbf6; border-color:#cfead8; } .clm-tw-factor.is-ok  .clm-tw-factor-v { color:#1e8449; }
.clm-tw-factor.is-bad { background:#fef5f4; border-color:#f5c2bc; } .clm-tw-factor.is-bad .clm-tw-factor-v { color:#c0392b; }

.clm-tw-res {
  display:flex; align-items:center; justify-content:space-between; gap:12px 20px; flex-wrap:wrap;
  padding:16px 20px; background:#fffcf0; border-top:1px solid #f1e2a0;
}
.clm-tw-res-k { font-size:13px; font-weight:700; color:#3a4451; text-transform:uppercase; letter-spacing:.6px; }
.clm-tw-res-f { margin-top:3px; font-size:12px; color:#7f8c9a; }
.clm-tw-res-v { margin-left:auto; font-size:30px; font-weight:700; line-height:1.1; color:#1a1a1a; white-space:nowrap; }
.clm-tw-res.is-ok  { background:#f4fbf6; border-top-color:#b9e3c6; } .clm-tw-res.is-ok  .clm-tw-res-v { color:#1e8449; }
.clm-tw-res.is-bad { background:#fef5f4; border-top-color:#f5c2bc; } .clm-tw-res.is-bad .clm-tw-res-v { color:#c0392b; }

/* ---------------------------------------------------------------------
6. Status tiles (list page)
--------------------------------------------------------------------- */
.clm-ls-stats { display:grid; grid-template-columns:repeat(3,minmax(0,1fr)); gap:12px; }
.clm-mr-stat {
  display:flex; flex-direction:column; gap:6px; padding:14px 16px; background:#fff;
  border:1px solid #dde3ea; border-top:4px solid #cdd4dc; border-radius:8px; cursor:pointer; text-align:left;
  transition:box-shadow .15s, background .15s;
}
.clm-mr-stat:hover { box-shadow:0 2px 8px rgba(0,0,0,.06); }
.clm-mr-stat:focus { outline:none; }
.clm-mr-stat-k { font-size:12px; font-weight:700; color:#3a4451; text-transform:uppercase; letter-spacing:.6px; }
.clm-mr-stat-v { font-size:26px; font-weight:700; line-height:1.1; }
.clm-mr-stat-s { font-size:11px; color:#7f8c9a; }
.clm-mr-stat.is-active { background:#fffcf0; border-color:#F3D54E; box-shadow:0 0 0 2px rgba(243,213,78,.35); }
.clm-mr-stat.st-pending { border-top-color:#2e86c1; } .clm-mr-stat.st-pending .clm-mr-stat-v { color:#2e86c1; }
.clm-mr-stat.st-history { border-top-color:#27ae60; } .clm-mr-stat.st-history .clm-mr-stat-v { color:#27ae60; }
.clm-mr-stat.st-all     { border-top-color:#1a1a1a; } .clm-mr-stat.st-all     .clm-mr-stat-v { color:#1a1a1a; }

/* ---------------------------------------------------------------------
7. Ageing table bucket colours
--------------------------------------------------------------------- */
tr.ag-group th.safe { background:#d9eedd; color:#14532d; }  tr.ag-sub th.safe { background:#edf7ef; color:#14532d; }
tr.ag-group th.warn { background:#fde4c4; color:#7a4100; }  tr.ag-sub th.warn { background:#fff4e5; color:#7a4100; }
tr.ag-group th.risk { background:#f8d7d3; color:#8f1d16; }  tr.ag-sub th.risk { background:#fdeeec; color:#8f1d16; }
.clm-table td.zero { color:#b0b9c4; }
.clm-table td.warn-val { color:#a15a00; font-weight:700; background:#fffaf2; }
.clm-table td.risk-val { color:#b3261e; font-weight:700; background:#fff6f5; }

/* ---------------------------------------------------------------------
8. Buttons & Utilities
--------------------------------------------------------------------- */
.clm-btn {
  display:inline-flex; align-items:center; justify-content:center; gap:6px; padding:8px 16px;
  border:1px solid transparent; border-radius:6px; font-size:13px; font-weight:700; line-height:1.2;
  cursor:pointer; white-space:nowrap; transition:background .15s, color .15s, border-color .15s;
  text-decoration:none !important;
}
.clm-btn[disabled] { opacity:.5; cursor:not-allowed; }
.clm-btn-sm   { padding:6px 12px; font-size:12px; }
.clm-btn-xs   { padding:4px 9px; font-size:11.5px; border-radius:4px; gap:4px; }
.clm-btn-reject  { background:#E23D28; color:#fff; }
.clm-btn-reject:hover:not([disabled])  { background:#b3261e; color:#fff; }
.clm-btn-ghost   { background:#fff; color:#1a1a1a; border-color:#cdd4dc; }
.clm-btn-ghost:hover:not([disabled])   { background:#1a1a1a; color:#F3D54E; border-color:#1a1a1a; }

.clm-ls-label { display:block; margin-bottom:6px; font-size:12px; font-weight:700; color:#3a4451; text-transform:uppercase; letter-spacing:.6px; }
.clm-ls-hint { margin-top:8px; font-size:12px; color:#7f8c9a; }
.clm-ls .input-group-addon { background:#fafbfc; border-color:#cfd6de; color:#7f8c9a; }
.clm-ls .form-control { display:block; width:100%; padding:7px 10px; border:1px solid #cfd6de; border-radius:6px; box-shadow:none; height:auto; min-height:36px; font-size:13px; }
.clm-ls .input-group { display:table; width:100%; border-collapse:separate; }
.clm-ls .input-group .form-control { display:table-cell; border-radius:0 6px 6px 0; }
.clm-ls .input-group-addon { display:table-cell; width:1%; padding:0 12px; border:1px solid #cfd6de; border-right:0; border-radius:6px 0 0 6px; vertical-align:middle; }
.clm-ls-filter-grid { display:grid; grid-template-columns:2fr 1fr; gap:16px; }
.clm-ls-actions { display:flex; align-items:center; justify-content:flex-end; gap:10px; flex-wrap:wrap; padding:14px 20px; background:#fafbfc; border-top:1px solid #e6eaef; }
.clm-ls-processing { font-size:12px; color:#5a6a7a; }
.clm-ls-muted { color:#7f8c9a; font-size:12.5px; }
.clm-ls-text { margin:0; white-space:pre-wrap; font-size:13px; line-height:1.6; color:#1a1a1a; }

/* loading / empty */
.clm-ls-loading { padding:40px 20px; text-align:center; color:#5a6a7a; }
.clm-ls-loading i { color:#AF272F; }
.clm-ls-loading p { margin:10px 0 0; font-weight:700; }
.clm-ls-empty { margin-top:16px; padding:40px 20px; text-align:center; background:#fafbfc; border:1px dashed #cdd4dc; border-radius:8px; }
.clm-ls-empty i { color:#27ae60; }
.clm-ls-empty h4 { margin:10px 0 4px; font-size:16px; font-weight:700; color:#1a1a1a; }
.clm-ls-empty p { margin:0; color:#5a6a7a; }

/* queue table */
.clm-ls-table-wrap { border:0; border-radius:0; }
.clm-ls-table .clm-ls-left { text-align:left; }
.clm-ls-table th, .clm-ls-table td { padding:12px 12px; }
.clm-ls-table td.clm-ls-wrap { white-space:normal; min-width:170px; }
.clm-ls-table tbody tr:hover td { background:#fffdf3; }
.clm-ls-reqno { font-size:14px; font-weight:700; color:#1a1a1a; }
.clm-ls-pan { margin-top:3px; font-size:12px; font-weight:700; color:#1a1a1a; }
.clm-ls-meta { margin-top:3px; font-size:12px; color:#5a6a7a; }
.clm-ls-meta i { width:14px; color:#8a96a3; }
.clm-ls-seg { display:inline-block; margin-top:6px; padding:2px 8px; border-radius:4px; background:#f1f3f7; border:1px solid #dde3ea; color:#3a4451; font-size:11px; font-weight:700; }

/* status pill */
.clm-ls-status {
  display:inline-block; padding:4px 12px; border-radius:12px; border:1px solid; font-size:11.5px; font-weight:700;
  text-transform:uppercase; letter-spacing:.4px; white-space:nowrap;
}
.clm-ls-status.st-pending   { background:#eaf3fb; color:#2e86c1; border-color:#b8d6ee; }
.clm-ls-status.st-approved  { background:#eaf7ee; color:#1e8449; border-color:#b9e3c6; }
.clm-ls-status.st-rejected  { background:#fdecea; color:#b3261e; border-color:#f5c2bc; }
.clm-ls-status.st-cancelled { background:#f3f4f6; color:#5a6a7a; border-color:#dcdfe4; }
.clm-ls-status.st-work      { background:#fff4e0; color:#a15a00; border-color:#f6d39a; }

/* pager */
.clm-ls-pager {
  display:flex; align-items:center; justify-content:space-between; gap:12px; flex-wrap:wrap;
  padding:12px 20px; background:#fafbfc; border-top:1px solid #dde3ea; font-size:12.5px; color:#5a6a7a;
}
.clm-ls-pager-nav { display:flex; align-items:center; gap:10px; }
.clm-ls-pager-page { font-weight:700; color:#1a1a1a; }

/* 2x2 matrix */
.clm-ls-matrix { display:grid; grid-template-columns:repeat(2,minmax(0,1fr)); gap:16px; margin-top:16px; align-items:stretch; }
.clm-ls-cell { margin-top:0; display:flex; flex-direction:column; min-width:0; }
.clm-ls-cell > .clm-ls-actions { margin-top:auto; }

/* attached documents */
.clm-ls-doclist { display:flex; flex-direction:column; gap:8px; }
.clm-ls-doc {
  display:flex; align-items:center; gap:12px; padding:10px 12px; border:1px solid #dde3ea; border-radius:6px;
  background:#fafbfc; color:#1a1a1a; min-width:0;
}
.clm-ls-doc:hover { border-color:#cdd4dc; background:#fff; }
.clm-ls-doc-icon {
  flex-shrink:0; width:32px; height:32px; border-radius:6px; display:flex; align-items:center; justify-content:center;
  background:#eef1f5; color:#5a6a7a; font-size:15px;
}
.clm-ls-doc-icon.is-pdf { background:#fdecea; color:#E23D28; }
.clm-ls-doc-main { flex:1 1 auto; min-width:0; display:flex; flex-direction:column; gap:2px; }
.clm-ls-doc-name { font-size:13px; font-weight:700; overflow:hidden; text-overflow:ellipsis; white-space:nowrap; }
.clm-ls-doc-meta { font-size:11.5px; color:#7f8c9a; overflow:hidden; text-overflow:ellipsis; white-space:nowrap; }
.clm-ls-doc-actions { display:inline-flex; align-items:center; gap:6px; flex-shrink:0; margin-left:auto; }
.clm-ls-upload {
  display:flex; align-items:center; justify-content:space-between; gap:12px; flex-wrap:wrap;
  padding:14px 20px; border-top:1px dashed #e6eaef; margin-top:auto;
}

/* approval stepper */
.clm-ls-stepper { display:flex; align-items:flex-start; overflow-x:auto; padding:6px 0 4px; }
.clm-ls-step { position:relative; flex:1 1 0; min-width:150px; padding:0 8px; text-align:center; }
.clm-ls-step::before { content:""; position:absolute; top:16px; left:-50%; width:100%; height:2px; background:#dde3ea; z-index:0; }
.clm-ls-step:first-child::before { display:none; }
.clm-ls-step.completed::before, .clm-ls-step.current::before, .clm-ls-step.rejected::before { background:#27ae60; }
.clm-ls-step-icon {
  position:relative; z-index:1; width:34px; height:34px; margin:0 auto 8px; border-radius:50%;
  display:flex; align-items:center; justify-content:center; background:#fff; border:2px solid #cdd4dc;
  color:#8a96a3; font-size:13px; font-weight:700;
}
.clm-ls-step.completed .clm-ls-step-icon { background:#27ae60; border-color:#27ae60; color:#fff; }
.clm-ls-step.current .clm-ls-step-icon   { border-color:#2e86c1; color:#2e86c1; box-shadow:0 0 0 4px rgba(46,134,193,.18); }
.clm-ls-step.rejected .clm-ls-step-icon  { background:#E23D28; border-color:#E23D28; color:#fff; }
.clm-ls-step-name { font-size:12.5px; font-weight:700; color:#1a1a1a; white-space:nowrap; overflow:hidden; text-overflow:ellipsis; }
.clm-ls-step.is-me .clm-ls-step-name { color:#AF272F; }
.clm-ls-step-role { margin-top:2px; font-size:11px; color:#5a6a7a; text-transform:uppercase; letter-spacing:.4px; white-space:nowrap; overflow:hidden; text-overflow:ellipsis; }
.clm-ls-step-state { margin-top:4px; font-size:11px; font-weight:700; text-transform:uppercase; letter-spacing:.4px; color:#7f8c9a; }
.clm-ls-step.completed .clm-ls-step-state { color:#1e8449; }
.clm-ls-step.current .clm-ls-step-state   { color:#2e86c1; }
.clm-ls-step.rejected .clm-ls-step-state  { color:#b3261e; }
.clm-ls-you {
  display:inline-block; margin-top:6px; padding:2px 8px; border-radius:4px; background:#1a1a1a; color:#F3D54E;
  font-size:10px; font-weight:700; text-transform:uppercase; letter-spacing:.5px;
}

/* customer profile columns */
.clm-ls-cols { display:grid; grid-template-columns:repeat(2,minmax(0,1fr)); gap:20px; margin-top:16px; }
.clm-ls-col { background:#f4f4f1; border:1px solid #e0e6ed; border-radius:10px; padding:20px; min-width:0; }
.clm-col-heading {
  display:flex; align-items:center; gap:8px; padding-bottom:8px; border-bottom:2px solid #F3D54E;
  font-size:15px; font-weight:700; color:#1a1a1a; text-transform:uppercase; letter-spacing:.8px;
}
.clm-ls-col-donee .clm-col-heading i { color:#27ae60; }
.clm-ls-col-donor .clm-col-heading i { color:#E23D28; }
.clm-ls-flush { border:0; border-radius:0; }
.clm-ls-aging th, .clm-ls-aging td { padding:9px 10px; }
.clm-ls-aging tr.ag-group th, .clm-ls-aging tr.ag-sub th { font-size:11.5px; letter-spacing:.5px; }
.clm-ls-aging td { font-size:12.5px; }
.clm-ls-aging .clm-ls-left { text-align:left; }
.clm-ls-aging td.clm-ls-total { background:#FFF8D6; font-weight:700; }

.slide-down { animation:clmLsSlide .25s ease-out; }
@keyframes clmLsSlide { from { opacity:0; transform:translateY(-4px); } to { opacity:1; transform:translateY(0); } }

/* ---------------------------------------------------------------------
9. Responsive
--------------------------------------------------------------------- */
@media (max-width:1100px) {
  .clm-ls-cols { grid-template-columns:1fr; }
  .clm-ls-matrix { grid-template-columns:1fr; }
  .clm-tw-factors { grid-template-columns:repeat(2,minmax(0,1fr)); }
}
@media (max-width:991px) {
  .clm-hero-title { font-size:22px; }
  .clm-hero-side { align-items:flex-start; }
}
@media (max-width:768px) {
  .clm-ls { padding:16px; }
  .clm-section { padding:20px 16px; }

  .clm-ls-table thead { display:none; }
  .clm-ls-table, .clm-ls-table tbody, .clm-ls-table tr, .clm-ls-table td { display:block; width:100%; }
  .clm-ls-table tr { border-bottom:6px solid #f4f5f7; }
  .clm-ls-table td {
    display:grid; grid-template-columns:38% minmax(0,1fr); column-gap:12px; align-items:start;
    text-align:right !important; white-space:normal; border:0; border-bottom:1px solid #eef1f5; padding:10px 14px;
  }
  .clm-ls-table td > * { grid-column:2; justify-self:end; }
  .clm-ls-table td.grp { border-left:0 !important; }
  .clm-ls-table td::before {
    content:attr(data-label); grid-column:1; grid-row:1 / span 6; text-align:left;
    font-size:11px; font-weight:700; color:#5a6a7a; text-transform:uppercase; letter-spacing:.5px;
  }
  .clm-ls-table td.clm-ls-wrap { min-width:0; }
}
@media (max-width:640px) {
  .clm-hero { padding:22px 20px; }
  .clm-hero-title { font-size:20px; }
  .clm-hero-side { width:100%; }
  .clm-hero-stat { text-align:left; }
  .clm-hero-stat-v.is-amount { font-size:22px; }
  .clm-ls-stats { grid-template-columns:repeat(2,minmax(0,1fr)); }
  .clm-ls-stats .st-all { grid-column:1 / -1; }
  .clm-ls-filter-grid { grid-template-columns:1fr; }
  .clm-tw-factors { grid-template-columns:repeat(2,minmax(0,1fr)); }
  .clm-tw-res-v { font-size:24px; }
  .clm-ls-col { padding:14px; }
  .clm-ls-stepper { flex-direction:column; overflow:visible; gap:14px; }
  .clm-ls-step { display:grid; grid-template-columns:34px minmax(0,1fr); column-gap:12px; min-width:0; padding:0; text-align:left; }
  .clm-ls-step::before { top:-14px; left:16px; width:2px; height:14px; }
  .clm-ls-step-icon { grid-row:1 / span 4; margin:0; }
  .clm-mr-sap-tiles { grid-template-columns:1fr; }
}

/* ---------------------------------------------------------------------
10. Global Font Enforcement
--------------------------------------------------------------------- */
.clm-widget, .clm-widget *, .clm-widget input, .clm-widget select,
.clm-widget textarea, .clm-widget button, .clm-widget table {
  font-family:"Oxygen", "Source Sans Pro", "Helvetica Neue", Helvetica, Arial, sans-serif !important;
}
.clm-widget .fa { font-family:FontAwesome !important; }

sp_widget.script:
(function() {
    var CONFIG = {
        TABLES: {
            SWAP_REQUEST: 'x_birl3_clm_nt_limit_swap_request',
            CUSTOMER: 'x_birl3_clm_clm_customer_master1',
            OUTSTANDING_SNAPSHOT: 'x_birl3_clm_clm_aging_snapshot',
            APPROVER: 'sysapproval_approver',
            SEND_BACK: 'x_birl3_clm_clm_servicenow_to_sap_send_back'
        },
        SEND_BACK_CUSTOMER_TYPE: 'non_trade_limit_swap'
    };

    var userId = gs.getUserID();
    var userName = gs.getUserName();
    var isAdmin = gs.hasRole('x_birl3_clm.admin') || gs.hasRole('admin');
    data.isAdmin = isAdmin;

    function getInternalState(stateStr) {
        var s = (stateStr || '').toLowerCase();
        if (s.indexOf('pending') > -1 || s.indexOf('requested') > -1) return 'pending';
        if (s.indexOf('approved') > -1 || s.indexOf('complete') > -1 || s.indexOf('3') > -1) return 'approved';
        if (s.indexOf('reject') > -1) return 'rejected';
        if (s.indexOf('cancel') > -1 || s.indexOf('4') > -1) return 'cancelled';
        return 'work';
    }

    function formatGeo(code, name) {
        code = (code || '').toString().trim();
        name = (name || '').toString().trim();
        if (code && name) return name + ' (' + code + ')';
        if (name) return name;
        if (code) return code;
        return 'N/A';
    }

    function formatBytes(bytes) {
        var b = parseInt(bytes, 10);
        if (isNaN(b) || b <= 0) return '0 B';
        var k = 1024;
        var sizes = ['B', 'KB', 'MB', 'GB'];
        var i = Math.floor(Math.log(b) / Math.log(k));
        return parseFloat((b / Math.pow(k, i)).toFixed(1)) + ' ' + sizes[i];
    }

    function getApproverRole(appGr) {
        if (appGr.isValidField('approval_reason') && appGr.getValue('approval_reason')) {
            return appGr.getValue('approval_reason');
        }
        if (appGr.isValidField('u_role') && appGr.getValue('u_role')) {
            return appGr.getValue('u_role');
        }
        if (appGr.isValidField('u_approval_level') && appGr.getValue('u_approval_level')) {
            return appGr.getValue('u_approval_level');
        }
        return 'Approver';
    }

    function getLatestApprovalComment(appGr) {
        var jGr = new GlideRecord('sys_journal_field');
        jGr.addQuery('name', CONFIG.TABLES.APPROVER);
        jGr.addQuery('element_id', appGr.getUniqueValue());
        jGr.addQuery('element', 'IN', 'comments,work_notes');
        jGr.orderByDesc('sys_created_on');
        jGr.setLimit(1);
        jGr.query();
        if (jGr.next()) {
            return (jGr.getValue('value') || '').trim();
        }

        try {
            var raw = appGr.comments.getJournalEntry(1) || '';
            if (raw) {
                var lines = raw.split('\n');
                lines.shift();
                return lines.join('\n').trim();
            }
        } catch (e) {}

        return '';
    }

    var userNameCache = {};
    function getUserDisplayName(uName) {
        if (!uName) return '';
        if (userNameCache[uName] !== undefined) return userNameCache[uName];
        var uGr = new GlideRecord('sys_user');
        uGr.addQuery('user_name', uName);
        uGr.setLimit(1);
        uGr.query();
        userNameCache[uName] = uGr.next() ? (uGr.getValue('name') || uName) : uName;
        return userNameCache[uName];
    }

    function getAttachmentsForRecord(recordSysId) {
        var attList = [];
        var attGr = new GlideRecord('sys_attachment');
        attGr.addQuery('table_name', CONFIG.TABLES.SWAP_REQUEST);
        attGr.addQuery('table_sys_id', recordSysId);
        attGr.orderByDesc('sys_created_on');
        attGr.query();
        while (attGr.next()) {
            var fName = attGr.getValue('file_name') || '';
            var ext = fName.split('.').pop().toLowerCase();
            var attSysId = attGr.getUniqueValue();
            var uploader = attGr.getValue('sys_created_by') || '';

            attList.push({
                sys_id:           attSysId,
                name:             fName,
                size:             formatBytes(attGr.getValue('size_bytes')),
                ext:              ext,
                url:              '/sys_attachment.do?sys_id=' + attSysId,
                view_url:         '/sys_attachment.do?sys_id=' + attSysId + '&view=true',
                download_url:     '/sys_attachment.do?sys_id=' + attSysId,
                uploaded_by:      uploader,
                uploaded_by_name: getUserDisplayName(uploader),
                uploaded_on:      attGr.getDisplayValue('sys_created_on') || ''
            });
        }
        return attList;
    }

    // =========================================================================
    // MULTI-RECORD SAP SEND-BACK RESOLVER (Matches Non-Trade Pattern)
    // =========================================================================
    function addSendBackTypeFilter(sbGr) {
        if (sbGr.isValidField('customer_type')) {
            sbGr.addQuery('customer_type', CONFIG.SEND_BACK_CUSTOMER_TYPE);
        }
    }

    function addSwapSendBackConditions(sbGr, swapSysId, swapNumber) {
        var qc = null;
        if (sbGr.isValidField('nt_ls_request')) {
            qc = sbGr.addQuery('nt_ls_request', swapSysId);
        } else if (sbGr.isValidField('u_nt_ls_request')) {
            qc = sbGr.addQuery('u_nt_ls_request', swapSysId);
        } else if (sbGr.isValidField('nt_request')) {
            qc = sbGr.addQuery('nt_request', swapSysId);
        }

        if (qc) {
            if (swapNumber && sbGr.isValidField('u_request')) qc.addOrCondition('u_request', swapNumber);
            if (sbGr.isValidField('u_request')) qc.addOrCondition('u_request', swapSysId);
        } else if (sbGr.isValidField('u_request')) {
            qc = sbGr.addQuery('u_request', swapSysId);
            if (swapNumber) qc.addOrCondition('u_request', swapNumber);
        }
    }

    function readSendBackRows(swapSysId, swapNumber) {
        var rows = [];
        var sb = new GlideRecord(CONFIG.TABLES.SEND_BACK);
        addSwapSendBackConditions(sb, swapSysId, swapNumber);
        addSendBackTypeFilter(sb);
        sb.orderByDesc('sys_created_on');
        sb.query();

        while (sb.next()) {
            rows.push({
                sys_id: sb.getUniqueValue(),
                status: sb.getValue('u_status') || 'Failed',
                raw_status: (sb.getValue('u_status') || '').toLowerCase(),
                last_error: isAdmin ? (sb.getValue('u_last_error') || '') : '',
                customer_code: sb.getDisplayValue('u_customer_code') || '',
                credit_segment: sb.getValue('u_credit_segment') || '',
                attempt_count: parseInt(sb.getValue('u_attempt_count'), 10) || 0,
                approved_limit: parseFloat(sb.getValue('u_approved_code_limit')) || 0,
                processed_on: sb.getDisplayValue('u_processed_on') || sb.getDisplayValue('sys_created_on') || ''
            });
        }
        return rows;
    }

    // Evaluates multi-site breakdown across all units
    function getSapStatus(swapSysId, swapNumber, internalState) {
        var out = {
            sap_status: 'na', sap_label: '', sap_message: '', sap_on: '', sap_attempts: 0, sap_error: '', sap_can_retry: false,
            sap_total: 0, sap_ok: 0, sap_failed: 0, sap_pending: 0
        };
        if (internalState !== 'approved') return out;

        var rows = readSendBackRows(swapSysId, swapNumber);

        // Keep latest record per site code + segment
        var latestBySite = {};
        rows.forEach(function(r) {
            var key = (r.customer_code || 'ALL') + '|' + (r.credit_segment || 'ALL');
            if (!latestBySite[key]) latestBySite[key] = r;
        });

        var total = 0, ok = 0, failed = 0, pend = 0, lastOn = '', attempts = 0, errs = [];
        for (var k in latestBySite) {
            var lr = latestBySite[k];
            total++;
            attempts = Math.max(attempts, lr.attempt_count);
            var st = lr.raw_status;
            if (st === 'success' || st === 'processed') { 
                ok++; 
                if (lr.processed_on) lastOn = lr.processed_on; 
            } else if (st === 'failed') { 
                failed++; 
                if (lr.last_error) errs.push(lr.customer_code + ': ' + lr.last_error); 
            } else { 
                pend++; 
            }
        }

        out.sap_total = total;
        out.sap_ok = ok;
        out.sap_failed = failed;
        out.sap_pending = pend;

        if (total === 0) {
            out.sap_status = 'pending';
            out.sap_label = 'In Progress';
            out.sap_message = 'Approved. Both Donor and Donee limits are being queued in SAP.';
        } else if (failed > 0) {
            out.sap_status = 'failed';
            // Non-Trade Batch status pattern: check if partial or complete failure
            out.sap_label = (ok > 0) ? 'Partially Updated' : 'Failed';
            out.sap_message = (total > 1)
                ? ok + ' of ' + total + ' sites updated in SAP, ' + failed + ' failed' + (pend > 0 ? ', ' + pend + ' in progress' : '') + '. Limit reallocation not completely reflected in SAP.'
                : 'The SAP limit update failed after ' + attempts + ' attempts.';
            out.sap_error = isAdmin ? errs.join('\n') : '';
        } else if (pend > 0) {
            out.sap_status = 'pending';
            out.sap_label = 'In Progress';
            out.sap_message = ok + ' of ' + total + ' sites updated in SAP, ' + pend + ' in progress.';
        } else {
            out.sap_status = 'success';
            out.sap_label = 'Updated';
            out.sap_message = 'All ' + total + ' sites successfully updated in SAP' + (lastOn ? ' on ' + lastOn : '') + '.';
            out.sap_on = lastOn;
        }

        out.sap_attempts = attempts;
        out.sap_can_retry = (failed > 0) && isAdmin;
        return out;
    }

    function retrySapForSwap(swapSysId) {
        var res = { ok: false, message: '' };
        if (!isAdmin) { res.message = 'Only CLM admins can retry the SAP update.'; return res; }

        var rq = new GlideRecord(CONFIG.TABLES.SWAP_REQUEST);
        if (!swapSysId || !rq.get(swapSysId)) { res.message = 'Request not found.'; return res; }

        var rqDisp = rq.getDisplayValue('approval') || rq.getDisplayValue('state') || '';
        if (getInternalState(rqDisp) !== 'approved') { res.message = 'Only approved requests can be retried.'; return res; }

        var rqNumber = rq.getValue('number') || '';
        var sbRetry = new GlideRecord(CONFIG.TABLES.SEND_BACK);
        addSwapSendBackConditions(sbRetry, swapSysId, rqNumber);
        addSendBackTypeFilter(sbRetry);
        sbRetry.addQuery('u_status', 'Failed');
        sbRetry.query();

        var requeued = 0;
        while (sbRetry.next()) {
            sbRetry.setValue('u_status', 'Pending');
            sbRetry.setValue('u_attempt_count', 0);
            sbRetry.setValue('u_connection_retry_count', 0);
            sbRetry.setValue('u_last_error', 'Manual retry by ' + gs.getUserName() + ' at ' + new GlideDateTime().getDisplayValue());
            sbRetry.update();
            requeued++;
        }

        if (requeued > 0) {
            res.ok = true;
            res.message = 'Retry submitted for ' + requeued + ' failed unit(s). Updates will re-process shortly.';
        } else {
            res.message = 'No failed SAP transactions available to retry.';
        }
        return res;
    }

    // =========================================================================
    // 1. SAP RETRY (ADMIN ACTION)
    // =========================================================================
    if (input && input.action == 'retry_sap') {
        data.retryResult = retrySapForSwap(input.swapSysId);
        var sReq = new GlideRecord(CONFIG.TABLES.SWAP_REQUEST);
        if (sReq.get(input.swapSysId)) {
            var stDisp = sReq.getDisplayValue('approval') || sReq.getDisplayValue('state') || '';
            var sNum   = sReq.getValue('number') || '';
            data.sap = getSapStatus(input.swapSysId, sNum, getInternalState(stDisp));
            data.sendBackList = readSendBackRows(input.swapSysId, sNum);
        }
        return;
    }

    // =========================================================================
    // 2. POLL SAP STATUS
    // =========================================================================
    if (input && input.action == 'get_sap_status') {
        var pollGr = new GlideRecord(CONFIG.TABLES.SWAP_REQUEST);
        if (pollGr.get(input.swapSysId)) {
            var pState = pollGr.getDisplayValue('approval') || pollGr.getDisplayValue('state') || '';
            var pNum   = pollGr.getValue('number') || '';
            data.sap = getSapStatus(input.swapSysId, pNum, getInternalState(pState));
            data.sendBackList = readSendBackRows(input.swapSysId, pNum);
        }
        return;
    }

    // =========================================================================
    // 3. ATTACHMENT UPLOAD
    // =========================================================================
    if (input && input.action == 'upload_document') {
        var targetSwapRec = new GlideRecord(CONFIG.TABLES.SWAP_REQUEST);
        if (targetSwapRec.get(input.swapSysId)) {
            if (input.fileData && input.fileName && input.fileType) {
                new GlideSysAttachment().writeBase64(targetSwapRec, input.fileName, input.fileType, input.fileData);
            }
        }
        data.attachments = getAttachmentsForRecord(input.swapSysId);
        return;
    }

    // =========================================================================
    // 4. CANCEL REQUEST
    // =========================================================================
    if (input && input.action == 'cancel_swap') {
        var cancelGr = new GlideRecord(CONFIG.TABLES.SWAP_REQUEST);
        if (cancelGr.get(input.swapSysId)) {
            cancelGr.setValue('approval', 'rejected');
            cancelGr.setValue('state', '4');
            cancelGr.comments = "System Action: Limit Swap request cancelled by " + gs.getUserDisplayName() + ".";
            cancelGr.update();

            var appGr = new GlideRecord(CONFIG.TABLES.APPROVER);
            var qcApp = appGr.addQuery('sysapproval', input.swapSysId);
            qcApp.addOrCondition('document_id', input.swapSysId);
            appGr.addQuery('state', 'requested');
            appGr.query();
            while (appGr.next()) {
                appGr.setValue('state', 'cancelled');
                appGr.update();
            }

            data.success = true;
        } else {
            data.success = false;
        }
        return;
    }

    // =========================================================================
    // 5. FETCH SWAP REQUESTS LIST
    // =========================================================================
    if (input && input.action == 'fetch_swaps') {
        data.list = [];
        var swapList = new GlideRecord(CONFIG.TABLES.SWAP_REQUEST);

        if (!isAdmin) {
            var uQuery = swapList.addQuery('sys_created_by', userName);
            uQuery.addOrCondition('opened_by', userId);
        }

        swapList.orderByDesc('sys_created_on');
        swapList.query();

        while (swapList.next()) {
            var sSysId = swapList.getUniqueValue();
            var stateDisplay = swapList.getDisplayValue('approval') || swapList.getDisplayValue('state') || 'Pending';
            var num = swapList.getValue('number') || '';
            var intState = getInternalState(stateDisplay);

            var doneeCode = swapList.donee.customer_code_sap ? swapList.donee.customer_code_sap.toString() : '';
            var doneeName = swapList.donee.customer_name ? swapList.donee.customer_name.toString() : '';
            var donorCode = swapList.donor.customer_code_sap ? swapList.donor.customer_code_sap.toString() : '';
            var donorName = swapList.donor.customer_name ? swapList.donor.customer_name.toString() : '';

            var doneeZone = formatGeo(swapList.donee.zone.toString(), swapList.donee.zone_name.toString());
            var doneeReg  = formatGeo(swapList.donee.region.toString(), swapList.donee.region_name.toString());
            var doneeDep  = formatGeo(swapList.donee.depot.toString(), swapList.donee.depot_name.toString());

            var donorZone = formatGeo(swapList.donor.zone.toString(), swapList.donor.zone_name.toString());
            var donorReg  = formatGeo(swapList.donor.region.toString(), swapList.donor.region_name.toString());
            var donorDep  = formatGeo(swapList.donor.depot.toString(), swapList.donor.depot_name.toString());

            var sapInfo = getSapStatus(sSysId, num, intState);

            data.list.push({
                sys_id:            sSysId,
                number:            num,
                pan:               swapList.getValue('pan') || (swapList.donee.pan ? swapList.donee.pan.toString() : 'N/A'),
                requested_by:      swapList.getDisplayValue('opened_by') || swapList.getDisplayValue('sys_created_by') || '',

                donee_site:        doneeCode ? (doneeCode + ' — ' + doneeName) : doneeName,
                donee_segment:     swapList.getDisplayValue('donee_segment') || swapList.donee.getDisplayValue('segment') || '',
                donee_zone:        doneeZone,
                donee_region:      doneeReg,
                donee_depot:       doneeDep,
                donee_outstanding: parseFloat(swapList.getValue('donee_outstanding') || 0),

                donor_site:        donorCode ? (donorCode + ' — ' + donorName) : donorName,
                donor_segment:     swapList.getDisplayValue('donor_segment') || swapList.donor.getDisplayValue('segment') || '',
                donor_zone:        donorZone,
                donor_region:      donorReg,
                donor_depot:       donorDep,
                donor_outstanding: parseFloat(swapList.getValue('donor_outstanding') || 0),

                amount:            parseFloat(swapList.getValue('requested_amount') || 0),
                state:             stateDisplay,
                internalState:     intState,
                created_on:        (swapList.getDisplayValue('sys_created_on') || '').split(' ')[0],
                sys_created_on:    swapList.getDisplayValue('sys_created_on') || '',

                sap_status:        sapInfo.sap_status,
                sap_label:         sapInfo.sap_label,
                sap_message:       sapInfo.sap_message,
                sap_on:            sapInfo.sap_on,
                sap_attempts:      sapInfo.sap_attempts,
                sap_error:         sapInfo.sap_error,
                sap_can_retry:     sapInfo.sap_can_retry,
                sap_total:         sapInfo.sap_total,
                sap_ok:            sapInfo.sap_ok,
                sap_failed:        sapInfo.sap_failed,
                sap_pending:       sapInfo.sap_pending
            });
        }
        return;
    }

    // =========================================================================
    // 6. DRILLDOWN DETAILS LOOKUP
    // =========================================================================
    if (input && input.action == 'get_swap_details') {
        data.approvalData = [];
        data.extendedDetails = { donee: {}, donor: {} };
        data.justification = '';
        data.sendBackList = [];

        var swapGr = new GlideRecord(CONFIG.TABLES.SWAP_REQUEST);
        if (swapGr.get(input.swapSysId)) {
            var sNum = swapGr.getValue('number') || '';
            var sDisp = swapGr.getDisplayValue('approval') || swapGr.getDisplayValue('state') || '';
            var iState = getInternalState(sDisp);

            // Detailed multi-site array returned to the frontend
            data.sendBackList = readSendBackRows(input.swapSysId, sNum);

            // Approval Chain
            var grApp = new GlideRecord(CONFIG.TABLES.APPROVER);
            var qApp = grApp.addQuery('sysapproval', input.swapSysId);
            qApp.addOrCondition('document_id', input.swapSysId);
            grApp.orderBy('sys_created_on');
            grApp.query();

            var seq = 0;
            while (grApp.next()) {
                seq++;
                data.approvalData.push({
                    seq:        seq,
                    updated_ts: new GlideDateTime(grApp.getValue('sys_updated_on')).getNumericValue(),
                    approver:   grApp.getDisplayValue('approver') || 'System Approver',
                    state:      grApp.getDisplayValue('state') || 'Requested',
                    role:       getApproverRole(grApp),
                    updated:    grApp.getDisplayValue('sys_updated_on') || '',
                    comments:   getLatestApprovalComment(grApp),
                    isMe:       grApp.getValue('approver') == userId
                });
            }

            data.justification = swapGr.getValue('description') || swapGr.getValue('u_description') || swapGr.getValue('justification') || swapGr.getValue('u_justification') || '';

            var doneeSysId = swapGr.getValue('donee');
            var donorSysId = swapGr.getValue('donor');

            function getCustomerSnapshot(custSysId, fallbackLimit, fallbackOutstanding) {
                var d = {
                    name: 'N/A', code: 'N/A', zone: 'N/A', region: 'N/A', depot: 'N/A',
                    segment: 'N/A', limit: fallbackLimit, outstanding: fallbackOutstanding,
                    history: []
                };

                if (custSysId) {
                    var cGr = new GlideRecord(CONFIG.TABLES.CUSTOMER);
                    if (cGr.get(custSysId)) {
                        d.name = cGr.getValue('customer_name') || 'N/A';
                        d.code = cGr.getValue('customer_code_sap') || 'N/A';
                        d.segment = cGr.getDisplayValue('segment') || cGr.getValue('segment') || 'N/A';
                        d.zone = formatGeo(cGr.getValue('zone'), cGr.getValue('zone_name'));
                        d.region = formatGeo(cGr.getValue('region'), cGr.getValue('region_name'));
                        d.depot = formatGeo(cGr.getValue('depot'), cGr.getValue('depot_name'));
                    }

                    var outGr = new GlideRecord(CONFIG.TABLES.OUTSTANDING_SNAPSHOT);
                    outGr.addQuery('customer', custSysId);
                    outGr.orderByDesc('sys_created_on');
                    outGr.setLimit(6);
                    outGr.query();

                    while (outGr.next()) {
                        d.history.push({
                            date:   (outGr.getDisplayValue('snapshot_month') || '').split(' ')[0],
                            total:  parseFloat(outGr.getValue('total_outstanding') || 0),
                            b0_30:  parseFloat(outGr.getValue('b0_30') || outGr.getValue('bucket_0_30_days') || 0),
                            b31_45: parseFloat(outGr.getValue('b31_45') || outGr.getValue('bucket_31_45_days') || 0),
                            b46_60: parseFloat(outGr.getValue('b46_60') || outGr.getValue('bucket_46_60_days') || 0),
                            b61_75: parseFloat(outGr.getValue('b61_75') || outGr.getValue('bucket_61_75_days') || 0),
                            b76_90: parseFloat(outGr.getValue('b76_90') || outGr.getValue('bucket_76_90_days') || 0),
                            b_gt90: parseFloat(outGr.getValue('b_gt90') || outGr.getValue('bucket_91_120_days') || 0)
                        });
                    }
                }
                return d;
            }

            data.extendedDetails.donee = getCustomerSnapshot(
                doneeSysId,
                parseFloat(swapGr.getValue('donee_current_limit') || 0),
                parseFloat(swapGr.getValue('donee_outstanding') || 0)
            );

            data.extendedDetails.donor = getCustomerSnapshot(
                donorSysId,
                parseFloat(swapGr.getValue('donor_current_limit') || 0),
                parseFloat(swapGr.getValue('donor_outstanding') || 0)
            );
        }

        data.attachments = getAttachmentsForRecord(input.swapSysId);
        return;
    }

    if (!input || !input.action) {
        data.list = [];
    }
})();
